      "note": "8/17(月)は決算発表がほぼ一巡し、朝方の4〜6月期GDP(1次速報)と米8月NY連銀製造業景気指数が前場の方向感を左右する。地合い自体はTOPIX8連騰・日経4日続伸と強く、上値は8月限SQ値6万9,702円が意識される一方、日銀の9月追加利上げ観測が上げを抑える構図。お盆で参加者が細るため、指数を追うより8/14引け後の決算で明確な数値が出た個別に絞るほうが分がある。本日の答え合わせでは上位2銘柄(ネクソン・トレンドマイクロ)がいずれもストップ高／ストップ安の比例配分となり、シナリオの当否以前に売買が成立しなかった。この反省から、今回は「引け後に決算数値が確定していて、かつ当日ストップ配分になっていない＝翌朝すんなり寄る」銘柄だけをプラン化し、寄り遅れが濃厚なネクソンは意図的に見送り側へ回している。週明けは決算一巡後の閑散相場になりやすく、ポジションを引っ張らず日中で完結させる前提で見るのが無難。【8/17朝7時更新】CME先物は大取終値比+25円・ドル円159円35銭とほぼ横ばいで、指数のギャップは小さくプラン銘柄の個別材料がそのまま効きやすい寄り付きになりそう。夜間PTSは金曜夕方の値からさらに一段動いており、シチズン2,975円(+8.14%)・朝日インテック4,190円(+8.16%、高値引け)と買い方向の2銘柄は勢いを保った一方、日本電子は7,750円(-12.40%)とさらに売られた。荏原はPTS安値5,350円から5,450円(-7.00%)まで下げ渋っており、売り目線の根拠はやや弱まっている。8時50分のGDP1次速報の結果と、本日が期限とされる米イラン交渉の行方には注意。",
