      "note": "【朝7:00更新】米7月PPIの下振れを受けてCME日経先物が69,165円(大証比+905円)、ナイトセッションも69,140円(+880円)まで買われており、日経平均は800〜900円規模の大幅GUで寄る公算が大きい。地合いは追い風だが、指数自体が大きく跳ねて寄る日は個別銘柄も寄り値が高く付きやすく、寄り天リスクが平常時より高い点に注意したい。加えて8/14は8月限マイナーSQの算出日で、寄り付きはSQ値決定に絡んだ売買で指数・大型株ともに値動きが荒くなりやすい。決算集中期間の最終日で363社の発表が控えており、指数を追うよりも当日の新規開示が出た個別材料株に絞るほうが分がある地合いと考えられる。8/13の答え合わせでは「当日の新規開示があった大幅ギャップ銘柄はギャップ方向に素直に伸び、材料が前日からの持ち越しだった銘柄は寄り天になった」という差が出たため、今回は13日引け後に新規開示のあった銘柄を上位に、材料の裏付けが取れない急騰株は見送り側に置いている。朝の夜間PTSでは全5銘柄の気配を確認済みで、下記各プランのシナリオに反映した。お盆で商いが細り週末も控えるため、ポジションを翌週に持ち越さない前提で見るのが無難。",
