            "detail": "8/12 15:30発表。上期(1-6月)の連結経常利益は前年同期比2.2倍の162億円で、従来予想127億円を28.0%上回って着地した。未開示だった通期予想は経常320億円(前期比87.1%増)、営業利益314億円(同89.8%増)、売上1,038億円(同47.9%増)を提示し3期連続最高益見通し。生成AI関連のメモリ半導体向けプローブカード増産が牽引し、2Q単体の売上営業利益率は24.8%→35.1%へ急上昇した。未定だった期末一括配当は178円(前期95円)。夜間PTSは14,610円(17:55時点)で当日終値13,950円比+4.73%。",
