      "note": "【8/12朝7時更新】CME日経先物67,085円は大阪日中終値比-75円と横ばい圏で、指数のギャップによる有利不利はほぼない前提で寄り付きを迎える。休場中の米国株は2日続落したが、SOXは8/11に+0.87%と逆行高し、引け後のスーパー・マイクロの好決算でAIサーバー需要の強さが再確認された。ドル円も159円28銭と円安方向に振れており、光コンポーネント・半導体装置関連である精工技研の前提は8/10夕方時点より若干強まったと考え、スコアを70→72に引き上げた。一方で今晩21:30の米CPIを控えて東京時間は上値を追いにくく、寄り付き直後以外は様子見になりやすい点は変わらない。PTSについて重要な補足が2つある。第一に、8/11は祝日で夜間PTSが非開催のため最新値は依然として8/10夜のセッションのものであり、2営業日ぶんの情報が寄り前気配に一気に出る構図は変わらない。第二に、8/10夜PTSの最終値は精工技研23,800円(+12.96%、高値24,200円、出来高7,100株)、スクエニHD3,090円(+7.63%、出来高19,900株)、サンリオ1,283円(-11.79%、出来高772,500株)と、17時台に確認した値より買い方向は切り上がり、出来高も当初把握の2倍前後に増えている。とくにサンリオのPTS出来高77万株は薄い板の上の気配ではなく実需の売りが伴っていることを裏づける。逆にミナトHD2,948円とタツモ4,190円の「+20%」は、それぞれ前日終値＋制限値幅(500円/700円)にぴったり一致するストップ高価格での張り付きで、PTSの値幅上限による頭打ちにすぎない。出来高も5,000株・6,400株と極薄で、この+20%という数字は上値の目安としても実需の強さの証拠としても使えないため、両銘柄のスコアは据え置いた。5銘柄とも8/11に新規の適時開示・レーティング変更は出ていない(TDnetの8/11開示は全市場で2件のみ)。／以下は8/10夕方時点の記述: 8/10(月)の日経平均は+1,363円(+2.08%)と3営業日ぶりに急反発し、高値6万7,006円まで買われた。米7月雇用統計の下振れでSOXが+2.55%と急伸した流れをそのまま受けた形で、フジクラが売買代金6,596億円と全市場断トツの主役、リクルートHDがストップ高、シスメックス+19.89%、平田機工ストップ高と、決算が良かった銘柄に素直に資金が入る一日だった。ただし8/11(火)は山の日で休場のため、以下のプランはすべて8/12(水)の寄り付きが対象になる。この「丸1日の間」が今回いちばん大きな変数で、通常なら翌朝に集中する寄り成りが2営業日ぶんに分散し、PTSの気配値がそのまま寄り値に直結する度合いは平時より下がると考えている。加えて8/12は日本時間21:30に米7月CPIの発表が控えており、東京時間中は結果待ちのポジション調整が入りやすく、8/10の急騰直後だけに高値警戒からの利益確定も出やすい。銘柄選定では、この2日空きに耐えられる「事実として数字が動いた銘柄」を優先し、PTSの出来高が数千株以下で気配だけが飛んでいる銘柄はプランから外した。買い方向は精工技研・スクウェア・エニックスHD・ミナトHDの3本、売り方向は当日売買代金637億円と流動性が最も厚いサンリオ1本、そして決算内容とPTSが真逆に動いているタツモを見送り候補として挙げている。なお売り方向は8/5以降「寄り付きで売れない・売っても日中に戻される」形が3営業日続いており(8/7エムスリー・8/10三井金属とリガクHD)、サンリオのスコアもその実績を踏まえて抑えめに置いた。流動性ルール(当日売買代金10億円以上)により、PTS+19.4%のシンデン・ハイテックス(8.6億円)、PTS-13.8%のAKIBAホールディングス(9.3億円)、PTS+25%超の宮入バルブ(0.3億円)、S高比例配分のWaqoo(0.3億円)・内外テック(1.1億円)・デジタルハーツHD(2.9億円)はいずれもプラン化していない。",
