          "scenario": "8/10の15:30に1Q決算と通期予想の修正を開示した。27年3月期1Qの連結経常利益は前年同期比58倍の47.9億円に急拡大し、4-6月期の売上営業利益率が2.6%から20.7%へ急改善している。これを受けて通期経常を32億円→93億円(前期40.4億円)へ2.9倍上方修正し、従来の減益予想から一転して2.3倍増益・2期連続最高益の見通しに変わった。上期配当も従来12円→24円(前年同期は無配)へ倍増し、年間42円となる。当日の終値は2,448円(+8.70%)と日中から買われていたが、夜間PTSは2,948円(+20.42%)とさらに上を見ている。Xでもメモリ在庫の高値放出を材料視した投稿が複数出ており、材料の分かりやすさという点では8/10の開示の中でも上位に入る。【8/12朝更新・重要】このPTS 2,948円は前日終値2,448円＋制限値幅500円にぴったり一致するストップ高価格で、始値=高値=安値=現在値がすべて2,948円、出来高5,000株という「値幅上限での張り付き」だった。つまり+20.42%はPTSの制度上の上限であって、実需がそこで止まったことを意味しない。上値の目安としても買いの強さの証拠としても使えないため、スコアは48のまま据え置く。8/11は祝日でPTS自体が非開催、新規開示・レーティング変更もない(アナリストカバレッジなし)。SNSでは「10倍株」「20倍のポテンシャル」といった断定的で煽り色の強い投稿が8/10夜21時台に集中しており、5銘柄中もっとも過熱している点にも留意したい。",
          "entry": "PTS水準どおりなら+20%前後のギャップアップになるため寄り成りは取らない形が基本。寄り付いて板が落ち着き、寄り値を維持していることを確認してからに限る。当日売買代金13.3億円は流動性ルールの下限に近く、寄り付きで値がつくのに時間がかかる可能性を織り込んでおきたい。",
          "invalidation": "寄り値を明確に割り込んで前日終値2,448円方向へ戻し始めたら、上方修正が寄り付きで出尽くしになった形としてシナリオは無効。",
          "risk": "PTS出来高は夜間通算でも5,000株と極めて薄く、しかも全約定がストップ高価格2,948円で固まっているため、+20.42%という気配値は上値の目安として機能しない。翌朝の寄り値がこれより大きく上でも下でもおかしくない。当日すでに+8.70%と日中から買われており、決算を先回りした買いの利益確定が寄り付きにぶつかる構図でもある。8/10のAKIBAホールディングスは1Q経常4.5倍の好決算にもかかわらず、日中に+9.52%と先回りで買われていた反動でPTSが-13.81%へ急落しており、同じ型になる可能性がある。1Q経常58倍という数字は前年同期の水準が極端に低かったことの裏返しでもあり、絶対額の評価には注意が必要。当日売買代金13.3億円は今回のプラン中で最も薄く、寄り付きで成行が滑るリスクが相対的に高い。SNSの盛り上がりは思惑・煽りを含みうる点にも留意したい。",
