          "basis": "決算(26年12月期上期の連結経常利益が前年同期比88.7%減の2.7億円、通期計画35億円に対する進捗率7.7%＝5年平均41.5%を大幅に下回る、4-6月期単独は経常が同93.0%減の0.8億円で売上営業利益率14.1%→0.6%) × それにもかかわらずPTSは4,190円(+20.06%、17:41時点)で値上がり率上位 × ただしPTS出来高1,300株・売買代金5.45百万円と極めて薄く、17:00の初値から17:41まで一貫して4,190円で固定されており単一の高値約定で気配が動いていない疑いが強い × 当日売買代金14.9億円",
          "scenario": "8/10の15:30に上期決算を開示した。26年12月期上期(1-6月)の連結経常利益は前年同期比88.7%減の2.7億円で、通期計画35億円に対する進捗率はわずか7.7%と5年平均41.5%を大幅に下回る。4-6月期単独では経常が同93.0%減の0.8億円、売上営業利益率は14.1%から0.6%へ急低下した。それでも通期35億円は据え置かれており、株探の試算では下期に前年同期比23.0%増の32.3億円を稼ぐ必要があるという非常に重い計画が残る。ところが夜間PTSは+20.06%と真逆に動いている。同時刻に「子会社の増資(特定子会社化)に関するお知らせ」が開示されており市場がこちらを評価した可能性はあるが、PTS出来高は1,300株・売買代金545万円と極めて薄く、17:00の初値から17:41まで一貫して4,190円のまま動いていない。単一の高値約定で気配が固定されているだけの可能性が高く、この気配を根拠に翌営業日の寄り付きを買いに行くのはリスクに見合わないと考える。【8/12朝更新】夜間セッション終了後に確認すると、この4,190円は前日終値3,490円＋制限値幅700円にぴったり一致するストップ高価格で、始値=高値=安値=現在値がすべて4,190円、出来高6,400株。PTSの値幅上限で頭打ちになっているだけであり、+20.06%という数字自体に情報量はほとんどない。決算の中身(上期経常88.7%減・進捗率7.7%)と気配が真逆という構図は変わらず、見送り判断を維持する。8/11に新規開示はなく、直近レーティングは下方修正・決算前の6/23付「米系大手証券・強気継続・目標株価5,500円」のままで、減益決算を受けた見直しが休場明けに出る可能性は残る(未確認)。SNSでは「4,000円前後まで上がる」「ストップ高確定」といった強気投稿が8/11夜に複数出ているが、減益決算という事実と整合しておらず、材料を精査していない投稿の可能性が高い。",
          "entry": "寄り付きでの参加は見送りが基本。仮に見るとしても寄り成りは使わず、板と寄り前気配で実際の買い注文の厚みを確認し、値がついて寄り値を維持していることを確かめてからに限る。",
