          "scenario": "ICパッケージ基板の需要が想定を大きく上回ったことと円安が要因で、AIサーバー・汎用サーバー・スイッチIC向けの堅調な需要を見込むという内容。通期経常が前期比2.0〜2.1倍になる計算で、増額幅は本日の決算のなかで最大級。日中も+5.12%と買われているが、開示は15:40の引け後のため上方修正そのものは株価に入っていない。売買代金1,637億円と板が厚く寄りで値がつかないリスクが小さい点は、本日ストップ高でも比例配分となった東計電算・スズデン・JPMCとの決定的な違いになる。",
          "entry": "★朝更新: 夜間PTSが+23.2%まで進んだため、想定するギャップアップ幅を+15%前後からPTSのVWAP19,015円〜最終値20,120円(終値比+16〜23%)のレンジに引き上げる。寄り成行は使わない。寄り後に寄り値を割り込まずに揉み合い、出来高を伴って上値を切り上げるのを確認してからが目安。本日の答え合わせでＦＵＪＩが+14.04%のギャップアップから9:24を天井に寄り値を割り、9:30時点で既に-0.54%だったことを踏まえると、寄り直後5〜10分の値動きで方向が決まる可能性がある点は事前に想定しておきたい。",
          "invalidation": "寄り後に寄り値を明確に割り込んで戻りが弱い場合はシナリオ無効。前日終値16,330円まで値を消す展開になれば材料出尽くしと判断する。日経平均が寄りから下値を切り下げ、他の好決算銘柄も揃って寄り天になっている場合は、個別材料だけで逆行高を狙う前提が弱くなる。",
          "risk": "最大のリスクは寄り天。8/3→8/4の2日連続で、PTSで大きく買われた好決算銘柄がPTSの上げ幅をほぼ寄り値で使い切ってから下げる動きになっている(ＦＵＪＩはPTS+18.80%→寄り+14.04%→引け-4.09%、ワークマンはPTS+4.56%→寄り+3.41%→引け-0.17%)。PTS+15.1%はこのパターンに最もはまりやすい水準である。加えて同社は日中も+5.12%と既に買われており、その分だけ翌日の上値余地は削られている。株式分割の発表は需給面の思惑を呼ぶが業績とは別物で、分割自体を材料視した買いは長続きしないことが多い。8/5はホンダなど178社の決算が控えており、日中に指数と物色の向きが変わる可能性もある。★朝7:00更新: 夜間PTSは20,120円(終値比+23.21%)まで買い上がられて終値ベースの値上がり率1位となり、夕方時点の+15.1%からさらに8ポイント上振れした。寄り天リスクはその分だけ確実に大きくなっている。しかもPTSのVWAPは19,015.75円(終値比+16.4%)で、最終値20,120円は深夜02:51の高値そのまま。出来高98,000株は東証日中の約1%と薄く、実勢は最終値よりVWAP寄りの可能性がある。加えて日経平均自体が約1,500円のギャップアップで始まる計算のため、寄り値が指数もろとも高値になる形は十分ありうる。夜間の米市場でAMDが決算後の時間外で約-8%となった点も、半導体関連の一角には重しになりうる。",
