          "basis": "8/4 15:30発表の1Q(IFRS)で売上271.82億円(前年同期比+4.0%)と増収率が鈍化した事実 × 通期最終益計画275億円に対する進捗率22.7%が3年平均20.1%とほぼ同水準にとどまった × 通期予想(売上1,230億円/営業385億円/最終275億円＝前期比-1.8%の減益計画)を据え置き × 日中は決算期待で終値3,467円(+5.06%)まで買われており期待と内容のギャップが大きい × PTS 3,145円(17:55時点/終値比-9.3%)で全体の値下がり率1位 × 売買代金84.6億円で流動性ルールの上位基準(30億円以上)を満たす",
          "scenario": "増収率+4.0%に対して市場が織り込んでいたのは、日中+5.06%という反応が示すとおりもっと強い数字だった、という期待と実績のズレが下げの中身。営業利益率は30.5%→31.6%と改善しており業績そのものが崩れているわけではないが、通期が減益計画のまま据え置かれたため、上方修正を期待して当日買った資金の逃げ場がない状態になっている。本日のＪＶＣケンウッドが-6.67%のギャップダウンで寄った後もさらに-12.58%下げたように、この相場では失望決算の売りが寄り付きだけでは織り込みきらない傾向が2日続けて出ている、というのが売りシナリオの前提。",
          "entry": "PTS-9.3%からの大幅ギャップダウン寄りが想定されるため、寄り成行での売り参加は使わない。寄り後に寄り値を回復できず戻り高値を切り下げるのを確認してからが目安。本日のＪＶＣケンウッドは寄り直後に寄り値比+1.1%まで戻す場面があってから崩れており、寄り直後の反発を確認する時間は必ず取りたい。",
          "invalidation": "寄り後に寄り値を上抜けて出来高を伴い上値を切り上げる場合はシナリオ無効。営業利益率の改善(30.5%→31.6%)のほうが評価され、進捗率の平凡さは季節性として流される展開になれば前提は崩れる。前日終値3,467円を回復する動きになれば完全に無効。",
          "risk": "進捗率22.7%は3年平均20.1%をわずかに上回っており、『明確な未達』ではなく『期待外れ』にとどまる点が、本日のＪＶＣケンウッド(通期進捗6.6%)との大きな違いである。数字そのものは悪くないため、ギャップダウンで寄った後に押し目買いが入る余地は本日のＪＶＣより大きい。日中に+5.06%上げた分の利益確定が寄り付きで一巡すれば、そこから先の下値は限定的になりうる。8/5は178社の決算があり、電子部品セクター全体のセンチメントが他社の決算で一変する可能性もある。★朝7:00更新: 売りシナリオにとって不利な材料が2つ出た。第一に、夜間PTSは3,218.5円(終値比-7.17%、出来高55,400株)で、夕方の-9.3%から下げ幅を約2ポイント縮小している。17:04の安値3,098円から一貫して戻し歩調で、最終値はVWAP3,159.75円を上回っており、『売られっぱなし』ではなく夜間に押し目買いが入った形。第二に、CME先物が日経平均現物比で約1,527円高と1,500円級のギャップアップ相場になる計算で、指数がこれだけ上げる日に個別の失望決算だけで逆行安を取りにいく構図になる。ギャップダウンで寄った直後に指数連動で買い戻される展開は前日夕方時点の想定より起こりやすく、この2点を織り込んでスコアを66から58へ引き下げた。",
