          "basis": "8/4 15:30の適時開示で『生成AI需要に対応する光ファイバーケーブルの生産能力増強、総投資額1,000億円』を発表した事実(株探の報道は16:54)で、日中の株価には入っていない引け後材料 × 本日は非鉄金属が業種別騰落率+5.32%で上昇トップとなり、フジクラ+7.88%・住友電工+4.80%とセクターが揃って買われた地合い × 売買代金1,053.7億円で市場14位、約定回数64,235回で活況銘柄8位と流動性は最上位クラス × 同じテーマで日東紡が+14.23%(売買代金259.5億円)と個別材料なしに買われるなど、周辺まで資金が回っている × ★朝更新: 夜間PTSは3,875.5円(終値3,566円比+8.68%)で、出来高185,300株はプラン5銘柄で最多。始値3,780円→安値3,712.5円(17:47)→高値3,886円(20:04)→最終3,875.5円と一晩を通じて高値圏で安定して買われ、価格の裏付けは5銘柄中もっとも厚い × ★朝更新: 8/4の米ナスダックが+2.59%と大幅高でAI・データセンター関連への資金流入が続いている",
          "scenario": "生成AI向け光ファイバの増産に1,000億円という投資規模は、需要見通しに対する会社側の確信を示す数字として読まれやすい。開示が15:30、報道が16:54と引け後のため、日中の+11.44%はあくまでセクター全体の上昇によるもので、この材料そのものは織り込まれていない。データセンター・AIインフラというテーマに資金が向かい続けていれば、材料と地合いが同じ方向を向く、というのが基本シナリオ。ただし本日すでに+11.44%上げた後という出発点は明確に不利。★朝7:00更新: 夜間の材料は買い側に有利な方向に出た。米ナスダックが+2.59%と大幅高でAI関連の地合いが継続し、PTSも出来高185,300株と厚みを伴って+8.68%で終えている。イビデンのPTS+23.2%のような過熱感がなく、上げ幅が『材料の大きさに対して控えめ』な水準にとどまっている点は、寄り天になりにくいという意味でむしろプラスに働く。この2点を織り込みスコアを53から56へ引き上げ、ダイキンと入れ替えて3位とした。",
          "entry": "ギャップアップ寄りが想定されるため寄り成行は使わない。寄り後に寄り値を維持し、出来高を伴って上値を切り上げるのを確認してからが目安。設備投資の発表は業績への反映が先の話なので、初動の勢いが続かなければ深追いしない。★朝更新: 想定するギャップアップ幅はPTSのVWAP3,818円〜最終値3,875.5円(終値比+7〜9%)が目安。ただし日経平均自体が約1,500円のギャップアップで始まる計算のため、この銘柄の上げのうちどこまでが個別材料でどこからが指数連動かは寄り後の相対的な強さで見極めたい。",
          "invalidation": "寄り後に寄り値を割り込んで戻りが弱ければシナリオ無効。前日終値3,566円まで値を消せば材料出尽くしと判断する。フジクラ・住友電工など同セクターが揃って売られている場合は、テーマから資金が抜けたとみて見送る。★朝更新: 日経平均が1,500円級のギャップアップから失速して下値を切り下げる展開になれば、指数連動の下げに個別材料は勝てないため同様に無効とする。",
          "risk": "本日すでに+11.44%上げており翌日の上値余地が削られている点が最大のリスクで、日中+1.57%と未反応だったのに寄り天になった本日のＦＵＪＩよりも不利な出発点になる。設備投資の発表は決算のように数値で業績が確定する材料ではなく、1,000億円という金額のインパクトだけで買われた場合は長続きしにくい。増産は供給増でもあり、将来の需給緩和・価格下落を連想する見方が出れば逆に売り材料として扱われる可能性もある。非鉄・電線セクターは本日の上げが大きかったぶん利益確定売りが出やすく、セクターごと反落すれば個別材料は効かない。海外売上比率が高いため、ドル円が再び円高に振れた場合も逆風になる。★朝7:00更新: 指数が1,500円級のギャップアップで始まる相場では、個別の強さと指数連動の上げが混同されやすく、指数が寄り天になれば個別材料に関係なく巻き込まれる。CMEの当日レンジが安値62,920〜高値65,660と値幅2,740円に達した事実そのものが、この相場の振れの大きさを示している。加えて夜間にAMDが決算後の時間外で約-8%となっており、半導体・AI関連の一角には重しが残る点も意識しておきたい。",
