          "rank": 4,
          "code": "6367",
          "name": "ダイキン工業",
          "side": "sell",
          "stance": "増収+17.5%でも経常+1.6%・最終-1.7%。ただしPTS出来高7,300株のみで裏付けが薄い",
          "confidence": "中",
          "confidenceScore": 52,
          "basis": "8/4 15:30発表の1Qで売上1兆4,268.10億円(前年同期比+17.5%)と大幅増収の一方、営業1,305.60億円(同+7.6%)・経常1,208.11億円(同+1.6%)・最終801.36億円(同-1.7%)と利益が伸び悩んだ事実 × 売上営業利益率が10.0%→9.2%へ悪化 × 上期計画2,440億円に対する経常進捗率49.5%が5年平均50.8%をやや下回る × 通期予想(売上5兆1,500億円/営業4,360億円/経常4,140億円/最終2,780億円)を据え置き × 売買代金381.6億円・時価総額約7兆円で流動性ルールの上位基準を大きく満たす × ★朝更新: 夜間PTSは22,320円(終値23,765円比-6.08%)で確定したが、出来高はわずか7,300株とプラン5銘柄で最も薄く、値下がり率の裏付けとしては最も弱い",
          "scenario": "増収率+17.5%に対して経常が+1.6%、最終が-1.7%と、売上が伸びても利益が残らない構図がはっきり出ている。利益率の低下は原材料・物流費や販管費の増加を示唆し、単発要因より収益構造側の話として読まれやすい。日中は+2.02%と決算期待で買われて終えており、開示内容と株価の向きが逆になったまま引けている。時価総額7兆円の日経平均採用銘柄で板が非常に厚く、寄りで値がつかないリスクがほぼない点は扱いやすい。★朝7:00更新: 一方で売りシナリオの前提は夜間に2つ弱くなった。PTSはレンジ22,200〜22,560円と終始横ばいで価格発見が17時台にほぼ完了しており、出来高7,300株では-6.08%という数字を寄り値の予測に使いにくい。さらに日経平均が約1,500円のギャップアップで始まる計算で、指数寄与の大きい日経平均採用銘柄ほど個別の失望が指数連動の買いに薄められやすい。スコアを60から52へ引き下げ、古河電工と入れ替えて4位とした。",
          "entry": "★朝更新: PTS-6.08%程度のギャップダウン寄りが想定されるため寄り成行での売り参加は使わない。寄り後に寄り値を回復できず戻り高値を切り下げるのを確認してからが目安。大型株は1日の値幅が小さいぶん、損切り幅と利益確定の水準を先に決めておきたい。指数が大きく上げて始まる日なので、寄り直後の指数連動の戻りを確認する時間は前日想定よりも長めに取りたい。",
          "invalidation": "寄り後に寄り値を上抜けて出来高を伴い上値を切り上げる場合はシナリオ無効。通期据え置きが『下期の空調需要期を控えた保守的な置き方』と解釈し直されれば、進捗率のわずかな未達は材料でなくなる。前日終値23,765円を回復すれば完全に無効。",
          "risk": "上期進捗49.5%と5年平均50.8%の差は1.3ポイントしかなく、『明確な未達』とまでは言えない水準である点が最大の弱み。大型ディフェンシブとして押し目買いが入りやすい銘柄でもあり、寄り付きの下げが即座に拾われる展開は十分ありうる。値幅が小さいため、想定どおり下げても判定ラインの-0.5%に届かない引き分け決着になりやすい点も、本日のワークマン(oc-0.17%で引き分け)と同じ形になりうる。指数寄与の大きい銘柄なので日経平均そのものが強含めば個別の失望が薄まる可能性もある。★朝7:00更新: この最後のリスクが現実味を帯びた。CME先物は日経平均現物比で約1,527円高で、指数が大きく上げて始まる日に日経平均採用の大型株を売り方向で取りにいく形になる。PTSの出来高が7,300株しかなく-6.08%の裏付けが弱いことと併せ、5銘柄のなかで最も前提が揺らいだプランである。",
