          "confidence": "低",
          "confidenceScore": 22,
          "basis": "本日31,150円(+19.12%)で4営業日連続のストップ高となり上場来高値圏にある事実 × 株探のストップ高一覧に配分表記はなく場中に商いは成立、売買代金105.6億円・約定回数1,118回・VWAP30,167円と流動性自体は十分ある × ただし材料は7/30発表の通期営業益182億円→489億円・年間配当600円→1,640円への上方修正のままで、8/4に新規の開示はない × SNSでは@N46_marikaの『億り人大量発生すんぞ』、@m1saRioの『本気で資産を増やしたいなら⭐トーメンデバイス』など煽り色の強い投稿が増え、値幅への期待が先行している × 本日の答え合わせで3営業日連続この銘柄の見送り判断を外している",
          "scenario": "3日連続で見送り判断を外していることは事実として記録する。それでも見送りを続ける理由は、4連続ストップ高で上場来高値圏という位置に対して、材料が7/30発表分から一度も更新されていないこと。買い手がつく理由は半導体商社セクターへの資金集中と値幅期待だけで、株価だけが先行している状態が5日目に入る。1日の値幅が5,000円超と荒く、寄りから方向を取りにいく根拠が薄い、というのが見送り判断の理由。ただし取り逃しが続いていることも同時に事実であり、この判断が保守的すぎる可能性は認識しておく。",
          "entry": "見送りが基本。特別気配が出た場合はそれが解消して値がつくまで手を出さない。取る場合も寄り成行は使わず、値がついた後に寄り値を維持して出来高を伴い上値を切り上げるのを確認してから。1単元あたりの値幅が大きいので枚数を落とすことが前提になる。",
          "invalidation": "積極的なエントリーは見送り前提。評価を改めるとすれば、寄り後に平常の出来高で売買が成立し、キオクシアやダイトロンなど半導体・半導体商社関連が同じ方向に揃っているのが確認できた場合。逆に朝から他の半導体商社が反落していれば、需給だけで上げてきた分の巻き戻しが出やすい。",
          "risk": "見送りが外れる側のリスクは、半導体商社というテーマに資金が入り続けて5日連続のストップ高になる展開で、これは3日連続で現実化している。逆に手を出した場合のリスクは、高値圏で値がついた直後の急落と、連続ストップ高後に制限値幅が拡大された場合の下振れの大きさ。連続ストップ高は最後の1日で往復する形になりやすく、日数を重ねるほどその可能性は高まる。PER・配当利回りの指標面の割安感は買い材料として語られているが、メモリー市況を前提とした業績予想が変われば指標そのものが変わる点も意識しておきたい。★朝7:00更新: 夜間の情報は判断が割れる方向に出た。PTSは33,500円(終値31,150円比+7.54%、出来高11,600株)で、18:16につけた高値34,330円(+10.2%)からは失速して終えており、5営業日連続ストップ高(制限値幅を考えると+約4,000円)を織り込む水準までは買われていない。この点は見送り判断に沿う。一方でCME先物が日経平均現物比で約1,527円高、米ナスダックも+2.59%と半導体・AI関連に追い風が吹く地合いで、テーマ物色が続けば5日連続の可能性は残る。見送りは対象値が上昇すれば『外れ』と判定されるため、この地合いは見送り判断にとって明確な逆風である。3営業日連続で見送りを外している事実と併せ、スコアは25から22へ引き下げた。",
