          "entry": "PTS+5%前後のギャップアップ寄りが想定される。寄り成行は使わず、寄り後に寄り値を維持して上値を切り上げるのを確認してからが目安。売買代金33.6億円は基準を満たすが上位2銘柄より薄いため、寄り値の滑りには注意したい。",
          "invalidation": "寄り後に寄り値を割り込んで前日終値5,860円まで値を消す展開になればシナリオ無効。為替が円安方向に急速に戻し、本日の円高メリット物色が巻き戻される展開になれば、地合い面の追い風はなくなる。",
          "risk": "【朝更新】前日夕方に『円高メリット物色は介入効果が一時的との見方が広がれば急速に剥落しうる』と挙げていたリスクが、一晩で現実化した形になっている。ドル円は157円台まで戻しており、8/3にセリアやニトリHDが逆行高になった構図が8/4も続く保証はない。個別の決算内容だけで買われるかどうかが問われる展開になりやすく、その場合は上位3銘柄より材料のインパクトが一段落ちる点がそのまま効いてくる。/ 以下は前日夕方時点のリスク: 進捗率67.8%は5年平均を上回るとはいえ、FUJIの上方修正や塩野義の進捗90.5%に比べれば材料としてのインパクトは一段落ちる。会社側が通期計画を据え置いている点も、見出しの弱さになりうる。小売は天候や既存店売上に業績が左右されやすく、四半期の好調がそのまま通期に延長できるとは限らない。円高メリット物色そのものが、介入効果は一時的との見方が広がれば急速に剥落しうるテーマである点も意識しておきたい。PTSの出来高は公表されていない。"
