      "summary": "7/31(金)の東京市場は日経平均が前日比2,494円59銭高(+4.03%)の6万4,362円02銭と大幅続伸し、ザラ場では上げ幅が一時3,400円を超えて4営業日ぶりに6万5,000円台を回復した。前日の米国市場でマイクロソフトの好決算とラムリサーチの好ガイダンスを受けフィラデルフィア半導体株指数(SOX)が8.2%高と6営業日ぶりに急反発したことで、海外勢のリスク選好が戻りAI・半導体関連に買い戻しが集中した。ただし中身は前日以上に偏っている。TOPIXは4,003.30(+50.80 / +1.29%)と上昇率が日経平均の3分の1以下にとどまり、東証プライムは値上がり612に対し値下がり922・変わらず24と、指数が4%上げた日に下落銘柄のほうが1.5倍多いという歪んだ相場だった。業種別では非鉄金属+9.29%・電気機器+6.15%が突出し、それ以外はほぼ横ばい圏。ストップ高は33銘柄に達したが、うち比例配分(張り付き)が9銘柄で、キオクシア・村田製作所・パナソニックHD・イビデンなどAI関連の主力が場中ほとんど商いを伴わずに制限値幅上限へ達している。日銀は金融政策決定会合で政策金利を1.0%程度に据え置き、展望レポートで2026年度成長率見通しを0.6%へ上方修正した。植田総裁は会見で「金融環境が緩和的すぎると判断すれば利上げのペースを速めることもあり得る」とタカ派寄りに踏み込み、結果発表後は利益確定売りで上げ幅を縮小した。ドル円は7/30夜に163円74銭から157円94銭まで急落する政府・日銀の円買い介入(5兆円規模との観測)があった流れを引きずり、31日東京では160円台後半まで買い戻された後、植田会見中に一時160円割れ、夕方以降さらに水準を切り下げて18時時点で158円73銭で推移している。なお日経平均は7月月間では8.13%安と4カ月ぶりの下落で、下落率は3月以来の大きさ。今回の急騰はあくまで6月下旬から続く下落局面のなかの戻りという位置づけである。【8/3朝の更新】週末の情報で前提が2つ変わった。1つは為替で、7/30〜8/1の政府・日銀の介入が米通貨当局と連携した異例の日米協調介入だったことが8/2に判明し、政府は本日8/3に日米共同声明を発表する予定と報じられている(NHK)。7/30実施分だけで6〜7兆円規模との市場推計もあり(日経)、ドル円は7/31夕方の158円73銭からNY終値157円68銭までさらに円高が進んだ。もう1つはシカゴ日経平均先物で、7/31の米国市場はNYダウ+0.53%・ナスダック+1.00%と続伸したにもかかわらず、CME円建て9月限は63,270円と大阪取引所の日中終値63,720円に対し450円安で引けている。米株高よりも円高進行のほうが重く見られた形で、7/31の+4.03%の急騰をそのまま引き継ぐ地合いではない。さらに個別ではアップルが7-9月期見通しの未達で-7.35%と急落しており、7/31にストップ高比例配分で引けた村田製作所をはじめとするアップル関連サプライチェーンには直接の逆風となる。一方でアマゾンはAWS売上が前年同期比36.7%増、26年の設備投資計画を2,200億ドルへ引き上げると発表して急伸しており、データセンター・NAND需要という文脈では支援材料になる。SOX指数は+0.07%とほぼ横ばいだが、マイクロンは単日-5.90%とメモリー個別は弱い。",
