          "scenario": "本日の東証では終値1,764.5円(+0.31%)とほぼ横ばいで、15:30の開示内容は株価にまったく反映されていない。上方修正の中身は「G-SHOCK」と「CASIO WATCH」の2軸戦略が奏功した時計事業の伸びで、1Q単独の営業利益128.1億円は通期計画340億円に対して進捗38%と、数字としての説得力はある。半導体一極集中の反動で内需・消費関連に資金が分散する展開になれば受け皿になりやすい、というのが基本シナリオ。【朝更新】前日夕方に「円高の逆風は限定的」と書いたが、この見方は割り引く必要がある。同社の時計事業は海外売上比率が高く、157円台まで進んだ円高は電子部品ほどではないにせよ換算・価格競争力の両面で逆風になりうる。加えてCME先物が大阪比-450円で、地合いそのものが買い方向に不利な方向で始まる可能性が高い。材料の強さと未織り込みという骨格は変わらないため順位は上位に残すが、スコアは68→65へ引き下げた。",
          "entry": "PTS+15%前後からのギャップアップ寄りが想定されるため寄り成行は使わない。PTSの出来高は22,900株まで増え、夕方時点の2,200株よりは値位置の参考になるが、それでも東証の売買代金31.3億円に比べれば桁違いに薄く、+15.53%をそのまま寄り値の予測に使うのは危険である点は変わらない。寄り後に寄り値を割り込まずに揉み合い、出来高を伴って上値を切り上げるのを確認してからが目安。",
